/// Atomically write data to a file by writing to a temp file first,
/// then renaming into place. This prevents concurrent writers from
/// producing partially-written (corrupt) files.
fn atomic_write(&self, path: &Path, data: &[u8]) -> Result<()> {
    let mut tmp = tempfile::NamedTempFile::new_in(&self.root)
        .with_context(|| format!("Failed to create temp file in {:?}", self.root))?;
    tmp.write_all(data)
        .with_context(|| format!("Failed to write temp file for {:?}", path))?;
    tmp.persist(path)
        .with_context(|| format!("Failed to persist temp file to {:?}", path))?;
    Ok(())
}

/// Store content and return a cache entry.
pub fn store(
    &self,
    source_id: &str,
    template_name: &str,
    content: &str,
    ttl_seconds: u64,
) -> Result<CacheEntry> {
    self.ensure_dir()?;

    let content_path = self.content_path(source_id, template_name);
    self.atomic_write(&content_path, content.as_bytes())?;

    let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
        .with_size(content.len() as u64);

    self.save_metadata(&entry)?;

    Ok(entry)
}

