fn save_cache(&self, url: &str, content: &str) -> Result<()> {
    let cache_path = self.cache_path(url);
    if let Some(parent) = cache_path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    // Use atomic write (write to temp file, then rename) to prevent
    // corruption when multiple processes write to the same cache concurrently.
    let mut tmp = tempfile::NamedTempFile::new_in(
        cache_path.parent().expect("cache path has parent"),
    )?;
    std::io::Write::write_all(&mut tmp, content.as_bytes())?;
    tmp.persist(&cache_path)?;
    Ok(())
}

